// Package genfile is what the generators (cmd/kavun-gen, cmd/kavun-docs) share about their output: a generated
// file, writing a set of them to disk, and comparing them with the disk as a unified diff (-check).
package genfile

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strings"
)

// File is one generated file. A nil Content means the file must not exist (a stale generated file): Write deletes
// it, Check reports it while it exists.
type File struct {
	Path    string
	Content []byte
}

// Write applies the files to disk: writes each content (creating its directory), deletes each file whose content is
// nil. A file whose content is already on disk is left alone, timestamp included.
func Write(files []File) error {
	for _, f := range files {
		if f.Content == nil {
			if err := os.Remove(f.Path); err != nil && !errors.Is(err, fs.ErrNotExist) {
				return err
			}
			continue
		}
		if old, err := os.ReadFile(f.Path); err == nil && bytes.Equal(old, f.Content) {
			continue // unchanged: leave the file and its timestamp alone
		}
		if err := os.MkdirAll(filepath.Dir(f.Path), 0o755); err != nil {
			return err
		}
		if err := os.WriteFile(f.Path, f.Content, 0o644); err != nil {
			return err
		}
	}
	return nil
}

// Check compares the files with what is on disk and answers one unified diff per file that differs (a missing
// file diffs against empty content, a file that must not exist against its content); nil when all are in sync.
func Check(files []File) ([]string, error) {
	var diffs []string
	for _, f := range files {
		old, err := os.ReadFile(f.Path)
		if err != nil && !errors.Is(err, fs.ErrNotExist) {
			return nil, err
		}
		if bytes.Equal(old, f.Content) && (old != nil) == (f.Content != nil) {
			continue
		}
		diffs = append(diffs, UnifiedDiff(filepath.ToSlash(f.Path)+" (on disk)", filepath.ToSlash(f.Path)+" (generated)", string(old), string(f.Content)))
	}
	return diffs, nil
}

// generatedHeader matches the first line of a generated Markdown page, whatever tool wrote it:
// `<!-- Code generated by <tool> … DO NOT EDIT. -->`.
var generatedHeader = regexp.MustCompile(`^<!-- Code generated by \S+ .*DO NOT EDIT\. -->$`)

// IsGenerated reports whether a file's first line is a generated header (generatedHeader).
func IsGenerated(content []byte) bool {
	line, _, _ := bytes.Cut(content, []byte("\n"))
	return generatedHeader.Match(bytes.TrimSuffix(line, []byte("\r")))
}

// Tree answers the files of a wholly generated directory: one per entry of contents (keyed by its slash-separated
// path below dir), in path order, followed by a deletion for every file already under dir that contents does not
// hold. A dir that does not exist yet holds nothing stale.
//
// Every file already under dir must be a generated one (IsGenerated), whatever its kind: a file without the header
// — a hand-written page, an image — means dir is not the generated directory it was taken for, and Tree refuses,
// naming each such file, before anything is written or deleted.
func Tree(dir string, contents map[string][]byte) ([]File, error) {
	rels := make([]string, 0, len(contents))
	for rel := range contents {
		rels = append(rels, rel)
	}
	slices.Sort(rels)

	var out []File
	produced := map[string]bool{}
	for _, rel := range rels {
		p := filepath.Join(dir, filepath.FromSlash(rel))
		produced[p] = true
		out = append(out, File{Path: p, Content: contents[rel]})
	}
	var foreign []string
	err := filepath.WalkDir(dir, func(p string, e fs.DirEntry, err error) error {
		if err != nil {
			if errors.Is(err, fs.ErrNotExist) && p == dir {
				return fs.SkipAll // no directory yet: nothing can be stale
			}
			return err
		}
		if e.IsDir() {
			return nil
		}
		if ok, err := startsGenerated(p); err != nil {
			return err
		} else if !ok {
			foreign = append(foreign, filepath.ToSlash(p))
		}
		if !produced[p] {
			out = append(out, File{Path: p}) // stale
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	if len(foreign) > 0 {
		return nil, fmt.Errorf("%s is wholly generated, but holds files that are not (no generated header); refusing to replace or delete them — move them out, or choose another directory:\n\t%s", filepath.ToSlash(dir), strings.Join(foreign, "\n\t"))
	}
	return out, nil
}

// startsGenerated reports whether the file at p starts with a generated header; only its first line is read.
func startsGenerated(p string) (bool, error) {
	f, err := os.Open(p)
	if err != nil {
		return false, err
	}
	defer f.Close()
	line, err := bufio.NewReader(f).ReadSlice('\n')
	if err != nil && !errors.Is(err, bufio.ErrBufferFull) && len(line) == 0 {
		return false, nil // empty (or unreadable as text): not generated
	}
	return IsGenerated(line), nil
}
